<script setup>
defineProps({candidates:Array,winner:String,player:String});defineEmits(['inspect','choose','back','confirm']);
</script>
<template><div class="decision-layout"><div class="eyebrow">第三幕　／　汇总裁定</div><h1 class="section-title">你准备签下谁的名字？</h1><p class="subtitle">本次颁发1份荣誉证书。其他委员意见附卷，最终名单由{{ player }}裁定。</p><div class="decision-list"><article v-for="c in candidates" :key="c.id" class="decision-card" :class="{chosen:winner===c.id}"><h3>{{ c.name }}</h3><div class="eyebrow">{{ c.college }}</div><p>十二岁：{{ c.archive.title }}</p><p>{{ c.form.realization }}</p><div class="actions"><button class="small" :data-action="'inspect-'+c.id" @click="$emit('inspect',c.id)">复核材料</button><button :class="winner===c.id?'brush':'small'" :data-action="'winner-'+c.id" @click="$emit('choose',c.id)">{{ winner===c.id?'✓ 已推荐':'推荐获奖' }}</button></div></article></div><p class="decision-note">{{ winner?'拟定获奖者：'+candidates.find(c=>c.id===winner)?.name+'。签署后进入颁奖典礼。':'请先选择1名获奖者。没有自动评分，也没有唯一正确答案。' }}</p><div class="actions"><button data-action="back-review" @click="$emit('back')">返回答辩名单</button><button class="primary" data-action="confirm-winner" :disabled="!winner" @click="$emit('confirm')">签署名单，送交典礼 →</button></div></div></template>
